(()=>{const root=document.getElementById('studio-uplink');if(!root)return;const status=root.querySelector('[role=status]'),connect=root.querySelector('[data-connect]'),disconnect=root.querySelector('[data-disconnect]');let peer=null,stream=null,session=null,generation=0,starting=false;
const remove=async id=>{try{await fetch('/api/studio/multistream/whip/'+id,{method:'DELETE',keepalive:true});}catch{status.textContent='Local uplink stopped. Server cleanup could not be confirmed; check the server console.';}};
function stop(){generation++;starting=false;const id=session;session=null;peer?.close();peer=null;stream?.getTracks().forEach(t=>t.stop());stream=null;connect.disabled=false;disconnect.disabled=true;status.textContent='Programme uplink disconnected.';if(id)void remove(id);}
connect.onclick=async()=>{if(starting||peer)return;if(!window.confirm('Send the current Programme video and selected audio to your broadcast server? If that source is already selected for a live broadcast, viewers may see it immediately.'))return;const attempt=++generation;starting=true;connect.disabled=true;disconnect.disabled=false;let pc,out,id;try{out=window.createStudioUplink();stream=out;pc=new RTCPeerConnection();peer=pc;out.getTracks().forEach(t=>pc.addTrack(t,out));pc.onconnectionstatechange=()=>{if(attempt!==generation)return;if(pc.connectionState==='connected'){status.textContent='Programme connected to server. Check broadcast status and destination reception separately.';}else if(['failed','disconnected','closed'].includes(pc.connectionState)){stop();status.textContent='Programme connection ended. Check your network and reconnect.';}};status.textContent='Connecting Programme…';await pc.setLocalDescription(await pc.createOffer());await new Promise((resolve,reject)=>{if(pc.iceGatheringState==='complete')return resolve();const timer=setTimeout(()=>{pc.removeEventListener('icegatheringstatechange',check);reject(Error('Video network negotiation timed out.'));},10000);function check(){if(pc.iceGatheringState==='complete'){clearTimeout(timer);pc.removeEventListener('icegatheringstatechange',check);resolve();}}pc.addEventListener('icegatheringstatechange',check);});if(attempt!==generation)return;const r=await fetch('/api/studio/multistream/whip',{method:'POST',headers:{'content-type':'application/sdp'},body:pc.localDescription.sdp,signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok||!data.session)throw Error(data.error||data.message||'Programme connection unavailable');id=data.session;if(attempt!==generation){void remove(id);return;}session=id;await pc.setRemoteDescription({type:'answer',sdp:data.answer});if(attempt===generation&&pc.connectionState!=='connected')status.textContent='Programme negotiation accepted. Waiting for video connection…';}catch(e){if(attempt===generation){stop();status.textContent=e.message;}}finally{if(attempt===generation)starting=false;if(attempt!==generation){pc?.close();out?.getTracks().forEach(t=>t.stop());}}};disconnect.onclick=stop;window.addEventListener('pagehide',stop);
})();
